//! Access to the results database (schema: db/schema.sql).
//!
//! - [`entities`]: SeaORM entities, generated by sea-orm-cli (see README);
//!   regenerating replaces that folder only. Re-exported here, so
//!   `db::rustc_runs` works as well as `db::entities::rustc_runs`.
//! - [`connection`]: connecting to the database.
//! - [`queries`]: lookups of file metrics.
//! - [`upserts`]: writes that insert or overwrite a row.

pub mod connection;
// Generated: not every entity or prelude item is used by the runner.
#[allow(dead_code, unused_imports)]
pub mod entities;
pub mod queries;
pub mod upserts;

pub use entities::*;

#[cfg(test)]
mod tests {
    use sea_orm::{ActiveModelTrait, ActiveValue::Set, EntityTrait, TransactionTrait};

    use super::sea_orm_active_enums::RunStatus;
    use super::{rust_metrics, rustc_runs};

    #[tokio::test]
    #[ignore = "needs a running database"]
    async fn insert_and_read_back() -> Result<(), sea_orm::DbErr> {
        let db = super::connection::connect().await?;
        let txn = db.begin().await?;

        // rustc_runs.rs_sha256 references rust_metrics.
        let rs_sha256 = "ab".repeat(32);
        rust_metrics::ActiveModel {
            rs_sha256: Set(rs_sha256.clone()),
            measured_at: Set(chrono::Utc::now().fixed_offset()),
            loc: Set(Some(3)),
            ..Default::default()
        }
        .insert(&txn)
        .await?;

        let row = rustc_runs::ActiveModel {
            run_id: Set("test_run".into()),
            started_at: Set(chrono::Utc::now().fixed_offset()),
            suite: Set("crates100".into()),
            test: Set("cfg-if".into()),
            rs_sha256: Set(rs_sha256),
            iteration: Set(0),
            status: Set(RunStatus::TimedOut),
            wall_s: Set(Some(1.25)),
            phases: Set(Some(serde_json::json!({"typeck": 0.25}))),
            ..Default::default()
        }
        .insert(&txn)
        .await?;

        let read = rustc_runs::Entity::find_by_id(row.id).one(&txn).await?.unwrap();
        assert_eq!(read, row);
        assert_eq!(read.family, None);

        // Rolled back, so the test leaves no rows behind.
        txn.rollback().await?;
        assert!(rustc_runs::Entity::find_by_id(row.id).one(&db).await?.is_none());
        Ok(())
    }
}
